func layerProjectFamilyWebPagePending(profile LayerProfile, value *tg.WebPagePending) (bin.Object, bool, error) {
	if value == nil {
		return nil, false, &LayerCodecError{Operation: "project", Profile: profile, Semantic: LayerSemanticTypeWebPagePending, Reason: "nil canonical value"}
	}
	switch profile {
	case LayerProfile225, LayerProfile226, LayerProfile227, LayerProfile228, LayerProfile229, LayerProfile230, LayerProfile231, LayerProfile232:
		return value, true, nil
	default:
		return nil, false, &LayerCodecError{Operation: "project", Profile: profile, Semantic: LayerSemanticTypeWebPagePending, Reason: "unsupported exact profile"}
	}
}
